internal fun paymentSymbol(id: String): PaymentSymbol {
    val symbolId = when (id) {
        "Payment" -> "STAR"
        "Home" -> "HOME"
        "Health" -> "HEART"
        "Entertainment" -> "PLAY"
        "Work" -> "TOOLS"
        "Shopping" -> "SHOPPING"
        else -> id
    }
    return paymentIcons.firstOrNull { it.id == symbolId } ?: paymentIcons.first()
}
